3:    pg-prod-suite-policy.js — Package 1 / round 3, item 4 (option ب)
4:    ───────────────────────────────────────────────────────────────────
5:    The invariant worth locking is NOT "every suite sets a flag"; it is:
6: 
7:      No test suite may boot server/index.js with a production environment
8:      unless it either supplies a PostgreSQL URL or explicitly asserts that
9:      the boot is refused.
10: 
11:    That is the P0-1 contract expressed at the test-suite level, and it is
12:    the check that would have caught tests/arena5-recovery.js automatically
13:    (it booted production with live Redis and no DATABASE_URL, pinning the
14:    defect). Making ALLOW_MEMORY_FALLBACK mandatory across all 65 suites
15:    that touch server/index.js was rejected as pure churn: production is
16:    already hard-gated, so the flag carries no safety weight there — it only
17:    silences the dev/test warning, which is asserted below instead.
18: 
19:    Exit codes: 0 = green · 1 = check failed · 2 = NOT-RUN.
20: 
21:    Usage:  node tests/pg-prod-suite-policy.js
22:    ═══════════════════════════════════════════════════════════════════ */
23: 'use strict';
24: const fs = require('fs');
25: const path = require('path');
26: const { spawnSync } = require('child_process');
27: 
28: const ROOT = path.join(__dirname, '..');
29: const TESTS = path.join(ROOT, 'tests');
30: const NAME = 'pg-prod-suite-policy';
31: 
32: let pass = 0, fail = 0;
33: const fails = [];
34: function chk(name, cond, extra) {
35:   if (cond) { pass++; console.log('  ✅ ' + name); }
36:   else { fail++; fails.push(name); console.log('  ❌ ' + name + (extra ? '  —  ' + String(extra).slice(0, 400) : '')); }
37: }
