39: /* A suite "boots the server" if it names server/index.js in any of the shapes
40:    actually used here: a require/spawn path string, or the split form
41:    path.join(ROOT, 'server', 'index.js'). The split form matters — it is how
42:    tests/multi-instance.js spawns it, and a path-only pattern misses it. */
43: const BOOTS_SERVER = /server(\/|\\'|",\s*')index\.js|server\/index\.js|'server',\s*'index\.js'/;
44: const PROD_ENV = /NODE_ENV.{0,6}'production'|PAYESH_ENV.{0,6}'production'|NODE_ENV=production/;
